//
//   Branch B (outside span, UnconstrainedStep, no EOS, RenderedEndsWith detects "<<"):
//     We set insideConstrainedOut := true and currentConstrainedOut := [].
//     parser.IsValidPrefix([]) holds by the method-level requires parser.IsValidPrefix([]).
//
//   Branch C (inside span, CloseSpanIfComplete closes):
//     CloseSpanIfComplete postcondition guarantees
//     !insideConstrainedOut ==> currentConstrainedOut == [] and
//     insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut). Invariant preserved.
//
//   Branch D (inside span, CloseSpanIfComplete does not close, ConstrainedStep):
//     ConstrainedStep returns a parser-valid token or EOS; on EOS we break without updating state.
//     IsTokenValidNext confirms validity; AppendConstrainedToken postcondition gives
//     parser.IsValidPrefix(currentConstrainedOut + [next]), preserving the invariant.
//     If the token is not valid (unexpected), generated and currentConstrainedOut are unchanged;
//     invariant preserved because insideConstrainedOut is still true and was already valid.
//
// Invariant 2: progress
//   |generated| <= |generatedPrefix| + steps
//
//   Branch A (UnconstrainedStep, no EOS, no "<<"):
//     generated grows by exactly 1 (one token appended), steps grows by 1.
//     |generated| = prev|generated| + 1 <= (|generatedPrefix| + prev_steps) + 1
//                 = |generatedPrefix| + steps. ✓
//
//   Branch B (UnconstrainedStep, no EOS, "<<" detected):
//     Same single-token append and single step increment as Branch A. ✓
//
//   Branch C (CloseSpanIfComplete closes):
//     CloseSpanIfComplete postcondition: |cg| <= |generated| + 1.
//     steps grows by 1. |generated| <= prev|generated| + 1 <= |generatedPrefix| + steps. ✓
//
//   Branch D (ConstrainedStep, no EOS, valid, AppendConstrainedToken):
//     AppendConstrainedToken appends exactly one token to generated; steps grows by 1.
//     |generated| = prev|generated| + 1 <= |generatedPrefix| + steps. ✓
//     On EOS or invalid token: generated unchanged, steps grows by 1; bound still holds. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Solve step by step using plain text. Write your final answer on the last line as <<int(expr)>> or <<expr>>. Inside << >>: ONLY variable names (no {braces}), integers, +, -, *, /, //, %, (, ), int(). No ** operator, no LaTeX, no spaces inside expression. ALWAYS use int() for integer results. Examples: <<int(n*price+base)>>, <<total-2*n-m>>, <<int((a+b)*c/60)>>. One << >> at the very end only.");

var steps: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    }
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  } else {
    var cg, ci, cc, closed := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
    if closed {
      steps := steps + 1;
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
    } else {
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.ConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, eosToken);
      steps := steps + 1;
      if next == eosToken {
        break;
      }
      var valid := helpers.IsTokenValidNext(parser, currentConstrainedOut, next);
      if valid {
        var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
      }
    }
  }
}

